import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes()).trim();
        int n = s.length();
        long score = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '5') score += 2;
            if ((c - '0') % 2 == 1) score += 1;
            if (i > 0 && s.charAt(i - 1) == '3' && c == '3') score += 4;
        }
        char last = s.charAt(n - 1);
        if (last == '0' || last == '5') score += 6;
        // Maximal runs where each digit is exactly one more than the previous.
        for (int i = 0; i < n;) {
            int j = i + 1;
            while (j < n && s.charAt(j) == s.charAt(j - 1) + 1) j++;
            score += (long) (j - i) * (j - i);
            i = j;
        }
        System.out.println(score);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	s := strings.TrimSpace(string(data))
	n := len(s)
	var score int64
	for i := 0; i < n; i++ {
		if s[i] == '5' {
			score += 2
		}
		if (s[i]-'0')%2 == 1 {
			score++
		}
		if i > 0 && s[i-1] == '3' && s[i] == '3' {
			score += 4
		}
	}
	if s[n-1] == '0' || s[n-1] == '5' {
		score += 6
	}
	// Maximal runs where each digit is exactly one more than the previous.
	for i := 0; i < n; {
		j := i + 1
		for j < n && s[j] == s[j-1]+1 {
			j++
		}
		score += int64(j-i) * int64(j-i)
		i = j
	}
	fmt.Println(score)
}
